urlset:
{% spaceless %}
{% for url in urlset %}

    {{ url.location }}
    {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
    {% if url.changefreq %}{{ url.changefreq }}{% endif %}
    {% if url.priority %}{{ url.priority }}{% endif %}
    {% if url.alternates %}
    {% for alternate in url.alternates %}

    {% endfor %}
    {% endif %}
    {% for image in url.images %}

      {{ image.loc }}
      {% if image.title %}{{ image.title }}{% endif %}
      {% if image.caption %}{{ image.caption }}{% endif %}

    {% endfor %}

{% endfor %}
{% endspaceless %}
